var t=`0596-bansh`;var i=`world-0596`;var o=`MN`;var l=`east-asia`;var a=4;var g=58;var r={en:`Bansh`,ua:`Банш`};var s={en:`A traditional dish from Mongolia, centered on all-purpose flour, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Монголія. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 17 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 17 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:17,i:[[`all-purpose-flour`,380,`g`],[`water`,170,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:11,i:[[`ground-lamb`,500,`g`],[`yellow-onion`,240,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:18,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 12 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 12 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:12,i:[[`water`,1450,`ml`]]}];var d={slug:t,id:i,country:`MN`,region:l,servings:4,minutes:58,title:r,text:s,steps:u};export{o as country,d as default,i as id,g as minutes,l as region,a as servings,t as slug,u as steps,s as text,r as title};